<script setup>
import { computed, ref } from 'vue'
import { useSchoolStore } from '../stores/school'
const school = useSchoolStore()
const selected = ref('Ava Wilson')
const exam = ref('Mid-term examination')
const editableMarks = ref(school.marks.map(subject => ({ ...subject })))
const total = computed(() => editableMarks.value.reduce((sum, subject) => sum + Number(subject.score || 0), 0))
const average = computed(() => Math.round(total.value / editableMarks.value.length))
const grade = computed(() => average.value >= 90 ? 'A' : average.value >= 80 ? 'B' : average.value >= 70 ? 'C' : 'D')
const saved = ref(false)
function saveMarks() { school.saveMarks(editableMarks.value); saved.value = true; setTimeout(() => saved.value = false, 2500) }
</script>
<template><div class="page-intro"><div><div class="date-label">ACADEMIC RECORDS</div><h1>Examinations</h1><p>Review results and record subject marks for your students.</p></div><button class="primary-button" @click="saveMarks">{{ saved ? '✓ Saved locally' : 'Save marks' }}</button></div><div class="marks-controls"><label>Student<select v-model="selected" class="select-pill"><option>Ava Wilson</option><option>Noah Bennett</option><option>Mia Chen</option><option>Liam Patel</option></select></label><label>Examination<select v-model="exam" class="select-pill"><option>Mid-term examination</option><option>Unit assessment</option><option>Final examination</option></select></label><span class="marks-demo-tag">DEMO RESULTS</span></div><div class="marks-summary"><div class="marks-score-card"><span class="marks-orb">✦</span><small>OVERALL PERFORMANCE</small><strong>{{ average }}<small>%</small></strong><div><span class="grade-pill">Grade {{ grade }}</span><span class="positive-copy">↗ Looking great</span></div><div class="score-summary-footer"><span>{{ total }} / {{ editableMarks.length * 100 }} marks</span><span>{{ editableMarks.length }} subjects</span></div></div><section class="panel marks-chart-panel"><div class="panel-heading"><div><h2>Subject performance</h2><p>Results from {{ exam.toLowerCase() }}</p></div><span class="chart-tag">● Current exam</span></div><div class="bar-chart"><div v-for="subject in editableMarks" :key="subject.subject" class="bar-column"><span class="bar-value">{{ subject.score }}%</span><div class="bar-track"><i :style="{ height: `${subject.score}%`, background: subject.color }"></i></div><span class="bar-label">{{ subject.subject }}</span></div></div></section></div><section class="panel results-panel"><div class="directory-toolbar"><div><h2>Subject results</h2><p>Enter or update marks out of 100</p></div><span class="term-pill">Term 2 · 2024–25</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>SUBJECT</th><th>MARKS OBTAINED</th><th>GRADE</th><th>PERFORMANCE</th><th>TEACHER NOTE</th></tr></thead><tbody><tr v-for="subject in editableMarks" :key="subject.subject"><td><div class="subject-name"><i :style="{ background: subject.color }"></i><strong>{{ subject.subject }}</strong></div></td><td><div class="mark-input"><input v-model.number="subject.score" type="number" min="0" max="100" aria-label="Marks out of 100"/><span>/ 100</span></div></td><td><span class="grade-pill">{{ subject.score >= 90 ? 'A' : subject.score >= 80 ? 'B+' : 'C' }}</span></td><td><div class="result-progress"><i :style="{ width: `${subject.score}%`, background: subject.color }"></i></div></td><td class="teacher-note">{{ subject.score >= 90 ? 'Excellent work!' : 'Making good progress' }}</td></tr></tbody></table></div></section></template>
